#include <bits/stdc++.h>
using namespace std;

const int MOD = 1000000007;

int main() {
    int n, m, k;
    scanf("%d%d%d", &n, &m, &k);

    int mm = m;
    ++n;
    m = min(m, (n + 1) / 2);

    vector<vector<long long>> C(n + 1, vector<long long>(n + 1));
    for (int i = 0; i <= n; ++i) {
        C[i][0] = C[i][i] = 1;
        for (int j = 1; j < i; ++j)
            C[i][j] = min<long long>(k + 1LL, C[i - 1][j - 1] + C[i - 1][j]);
    }

    const size_t side = n + 1;
    const size_t depth = k + 1;
    const size_t total = side * side * depth;

    auto id = [side, depth](int i, int j, int x) {
        return (static_cast<size_t>(i) * side + j) * depth + x;
    };

    vector<int> cur(total), nxt(total);

    if (k >= 1) {
        for (int i = 2; i <= n; ++i)
            cur[id(i, i - 1, 1)] = 1;
    }

    int ans = 0;

    for (int mi = 1; mi <= m; ++mi) {
        for (int i = 2; i <= n; ++i) {
            for (int ki = 1; ki <= k; ++ki) {
                ans = (ans + 1LL * cur[id(i, 0, ki)] * (mm - mi + 1)) % MOD;
            }
        }

        if (mi == m)
            break;

        fill(nxt.begin(), nxt.end(), 0);

        for (int i = 2; i <= n; ++i) {
            for (int j = 1; j < i; ++j) {
                for (int ki = 1; ki <= k; ++ki) {
                    int value = cur[id(i, j, ki)];
                    if (value == 0)
                        continue;

                    for (int t = j; t + i <= n; ++t) {
                        long long product = 1LL * ki * C[t - 1][j - 1];
                        if (product > k)
                            continue;

                        int &destination = nxt[id(t + i, t - j, static_cast<int>(product))];
                        destination += value;
                        if (destination >= MOD)
                            destination -= MOD;
                    }
                }
            }
        }

        cur.swap(nxt);
    }

    printf("%d\n", ans);
    return 0;
}

#include <bits/stdc++.h>

using namespace std;

const int MOD = 1000000007;
int dp[2][105][105][105];
long long C[105][105];

int main() {
    int n, m, k;
    scanf("%d%d%d", &n, &m, &k);

    int mm = m;
    long long limit = static_cast<long long>(k) + 1;

    for (int i = 0; i < 105; ++i) {
        C[i][0] = C[i][i] = 1;
        for (int j = 1; j < i; ++j)
            C[i][j] = min(limit, C[i - 1][j - 1] + C[i - 1][j]);
    }

    ++n;
    m = min(m, (n + 1) / 2);

    int cur = 0;
    for (int i = 2; i <= n; ++i)
        dp[cur][i][i - 1][1] = 1;

    int ans = 0;

    for (int mi = 1; mi <= m; ++mi) {
        for (int i = 2; i <= n; ++i) {
            for (int ki = 1; ki <= k; ++ki) {
                ans = (ans + 1LL * dp[cur][i][0][ki] * (mm - mi + 1)) % MOD;
            }
        }

        if (mi == m)
            break;

        int nxt = cur ^ 1;
        memset(dp[nxt], 0, sizeof(dp[nxt]));

        for (int i = 2; i <= n; ++i) {
            for (int j = 1; j < i; ++j) {
                for (int ki = 1; ki <= k; ++ki) {
                    if (dp[cur][i][j][ki] == 0)
                        continue;

                    for (int t = j; t + i <= n; ++t) {
                        long long product = 1LL * ki * C[t - 1][j - 1];
                        if (product > k)
                            continue;

                        int &value = dp[nxt][t + i][t - j][product];
                        value = (value + dp[cur][i][j][ki]) % MOD;
                    }
                }
            }
        }

        cur = nxt;
    }

    printf("%d\n", ans);
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

const int MOD = 1000000007;

int main() {
    int n, m, k;
    if (scanf("%d%d%d", &n, &m, &k) != 3)
        return 0;

    const int originalM = m;
    ++n;
    m = min(m, (n + 1) / 2);

    if (m <= 0 || k <= 0) {
        printf("0\n");
        return 0;
    }

    vector<vector<int>> C(n + 1, vector<int>(n + 1));
    const long long cap = (long long)k + 1;

    for (int i = 0; i <= n; ++i) {
        C[i][0] = C[i][i] = 1;
        for (int j = 1; j < i; ++j)
            C[i][j] = (int)min(cap, (long long)C[i - 1][j - 1] + C[i - 1][j]);
    }

    const int side = n + 1;
    const int depth = k + 1;
    const size_t states = (size_t)side * side * depth;

    vector<int> dp(states), nextDp(states);

    auto index = [side, depth](int i, int j, int value) -> size_t {
        return ((size_t)i * side + j) * depth + value;
    };

    for (int i = 2; i <= n; ++i)
        dp[index(i, i - 1, 1)] = 1;

    int answer = 0;

    for (int mi = 1; mi <= m; ++mi) {
        for (int i = 2; i <= n; ++i) {
            for (int value = 1; value <= k; ++value) {
                answer = (answer +
                          (long long)dp[index(i, 0, value)] *
                          (originalM - mi + 1)) % MOD;
            }
        }

        if (mi == m)
            break;

        fill(nextDp.begin(), nextDp.end(), 0);

        for (int i = 2; i <= n; ++i) {
            for (int j = 1; j < i; ++j) {
                for (int value = 1; value <= k; ++value) {
                    int current = dp[index(i, j, value)];
                    if (current == 0)
                        continue;

                    for (int t = j; t + i <= n; ++t) {
                        long long newValue = (long long)value * C[t - 1][j - 1];
                        if (newValue > k)
                            continue;

                        int &destination =
                            nextDp[index(t + i, t - j, (int)newValue)];
                        destination += current;
                        if (destination >= MOD)
                            destination -= MOD;
                    }
                }
            }
        }

        dp.swap(nextDp);
    }

    printf("%d\n", answer);
    return 0;
}

