    }

    const size_t N = n + 1;
    const size_t K = k + 1;
    const size_t stateCount = N * N * K;

    auto index = [N, K](int i, int j, int value) -> size_t {
        return (static_cast<size_t>(i) * N + j) * K + value;
    };

    vector<int> current(stateCount, 0), next(stateCount, 0);

    for (int i = 2; i <= n; ++i)
        current[index(i, i - 1, 1)] = 1;

    long long answer = 0;

    for (int mi = 1; mi <= m; ++mi) {
        for (int i = 2; i <= n; ++i) {
            for (int value = 1; value <= k; ++value) {
                answer += (long long)current[index(i, 0, value)] *
                          (originalM - mi + 1);
                answer %= MOD;
            }
        }

        if (mi == m)
            break;

        fill(next.begin(), next.end(), 0);

        for (int i = 2; i <= n; ++i) {
            for (int j = 1; j < i; ++j) {
                for (int value = 1; value <= k; ++value) {
                    int ways = current[index(i, j, value)];
                    if (ways == 0)
                        continue;

                    for (int t = j; t + i <= n; ++t) {
                        long long newValue = (long long)value * C[t - 1][j - 1];
                        if (newValue > k)
                            continue;

                        size_t pos = index(t + i, t - j, (int)newValue);
                        next[pos] += ways;
                        if (next[pos] >= MOD)
                            next[pos] -= MOD;
                    }
                }
            }
        }

        current.swap(next);
    }

    printf("%lld\n", answer);
    return 0;
}

